import 'package:flutter/material.dart'; import 'package:go_router/go_router.dart'; import '../../repositories/auth_repository.dart';
class AuthScreen extends StatefulWidget{const AuthScreen({super.key});@override State<AuthScreen>createState()=>_AuthScreenState();}
class _AuthScreenState extends State<AuthScreen>{final email=TextEditingController(),password=TextEditingController(),username=TextEditingController();bool signup=false,busy=false;String?error;final repo=AuthRepository();Future<void>submit()async{setState(()=>busy=true);try{if(signup)await repo.signUp(email.text.trim(),password.text,username.text.trim());else await repo.signIn(email.text.trim(),password.text);if(mounted)context.go('/');}catch(e){setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('图趴 PicParty')),body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:480),child:Column(children:[const FlutterLogo(size:72),const SizedBox(height:20),if(signup)TextField(controller:username,decoration:const InputDecoration(labelText:'Username')),const SizedBox(height:12),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email')),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error!=null)Padding(padding:const EdgeInsets.all(12),child:Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error))),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:submit,child:Text(busy?'...':signup?'Create account':'Sign in'))),TextButton(onPressed:()=>setState(()=>signup=!signup),child:Text(signup?'Already have an account? Sign in':'Create a new account'))])))));}
